-- Synthetic-only authorization fixture for isolated CI Postgres, not a production schema dump.
create role anon nologin;
create role authenticated nologin;
create schema auth;
create schema private;
create schema storage;
grant usage on schema public,auth,private,storage to anon,authenticated;
create table auth.users(id uuid primary key,email text not null);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create table public.projects(id uuid primary key,owner_user_id uuid not null,timezone text default 'Europe/Berlin');
create table public.tasks(id uuid primary key,project_id uuid references public.projects(id),project_task_uid integer,active boolean default true,is_summary boolean default false,baseline_start timestamptz,baseline_finish timestamptz);
create table public.resources(id uuid primary key,project_id uuid references public.projects(id),auth_user_id uuid,access_enabled boolean default true);
create table public.task_resources(task_id uuid references public.tasks(id),resource_id uuid references public.resources(id));
create table public.progress_updates(id uuid primary key default gen_random_uuid(),project_id uuid,task_id uuid,resource_id uuid,author_user_id uuid);
create table public.media(id uuid primary key default gen_random_uuid(),project_id uuid,storage_path text,task_id uuid,resource_id uuid,author_user_id uuid);
create table public.plan_imports(id uuid primary key,project_id uuid);
create table public.plan_import_changes(id uuid primary key,import_id uuid);
create table public.plan_task_revisions(id uuid primary key,project_id uuid);
create table public.project_checkpoints(id uuid primary key,project_id uuid);
create table public.weekly_snapshots(id uuid primary key,project_id uuid);
create table public.resource_access_events(id uuid primary key,project_id uuid);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,owner_id text);
create function storage.foldername(name text) returns text[] language sql immutable as $$ select string_to_array(name,'/') $$;
create function public.is_project_owner(p_project uuid) returns boolean language sql stable set search_path='' as $$ select exists(select 1 from public.projects p where p.id=p_project and p.owner_user_id=(select auth.uid())) $$;
-- Minimal legacy assignment helper; fixture only.
create function private.has_assigned_task_access(p_task_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.task_resources tr join public.resources r on r.id=tr.resource_id where tr.task_id=p_task_id and r.auth_user_id=auth.uid() and r.access_enabled)
$$;
create function public.apply_project_xml_plan_with_resources(p_project_id uuid,p_file_name text,p_plan jsonb,p_resources jsonb,p_assignments jsonb) returns jsonb language sql as $$ select '{}'::jsonb $$;
grant select,insert,update,delete on all tables in schema public,storage to authenticated;
alter table public.projects enable row level security;
create policy project_owner on public.projects for all to authenticated using(owner_user_id=auth.uid()) with check(owner_user_id=auth.uid());
alter table public.tasks enable row level security;
create policy task_owner on public.tasks for all to authenticated using(public.is_project_owner(project_id)) with check(public.is_project_owner(project_id));
create policy task_resource on public.tasks for select to authenticated using(private.has_assigned_task_access(id));
alter table public.resources enable row level security;
create policy resource_owner on public.resources for all to authenticated using(public.is_project_owner(project_id)) with check(public.is_project_owner(project_id));
create policy resource_self on public.resources for select to authenticated using(auth_user_id=auth.uid());
alter table public.task_resources enable row level security;
create policy link_owner on public.task_resources for all to authenticated using(exists(select 1 from public.tasks t where t.id=task_id and public.is_project_owner(t.project_id))) with check(exists(select 1 from public.tasks t where t.id=task_id and public.is_project_owner(t.project_id)));
alter table public.progress_updates enable row level security;
create policy report_owner_read on public.progress_updates for select to authenticated using(public.is_project_owner(project_id));
create policy report_resource_write on public.progress_updates for insert to authenticated with check(author_user_id=auth.uid() and (public.is_project_owner(project_id) or private.has_assigned_task_access(task_id)));
alter table public.media enable row level security;
create policy media_owner_read on public.media for select to authenticated using(public.is_project_owner(project_id));
create policy media_resource_write on public.media for insert to authenticated with check(author_user_id=auth.uid() and (public.is_project_owner(project_id) or private.has_assigned_task_access(task_id)));
alter table public.plan_imports enable row level security;
create policy imports_owner on public.plan_imports for select to authenticated using(public.is_project_owner(project_id));
alter table public.plan_import_changes enable row level security;
create policy changes_owner on public.plan_import_changes for select to authenticated using(exists(select 1 from public.plan_imports p where p.id=import_id and public.is_project_owner(p.project_id)));
alter table public.plan_task_revisions enable row level security;
create policy revisions_owner on public.plan_task_revisions for select to authenticated using(public.is_project_owner(project_id));
alter table public.project_checkpoints enable row level security;
create policy checkpoints_owner on public.project_checkpoints for select to authenticated using(public.is_project_owner(project_id));
alter table public.weekly_snapshots enable row level security;
create policy snapshots_owner on public.weekly_snapshots for select to authenticated using(public.is_project_owner(project_id));
alter table public.resource_access_events enable row level security;
create policy events_owner on public.resource_access_events for select to authenticated using(public.is_project_owner(project_id));
alter table storage.objects enable row level security;
create policy legacy_storage_write on storage.objects for insert to authenticated with check(bucket_id='task-media' and owner_id=auth.uid()::text);
